export type VendorMessageKey = typeof rows[number][0];
function column(index:1|2|3|4|5|6):Record<VendorMessageKey,string> {
  return Object.fromEntries(rows.map(row => [row[0], row[index]])) as Record<VendorMessageKey,string>;
}
export const vendorMessages = defineCatalogue({en:column(1),sw:column(2),fr:column(3),'zh-Hans':column(4),ru:column(5),es:column(6)});
